#define _POSIX_C_SOURCE 200809L

/*
 * OIDC login against a fake identity provider on 127.0.0.1: a JWKS endpoint and a token endpoint
 * that hands out one-time authorization codes, with RSA and EC keys generated by OpenSSL at run
 * time. Java's flow has no discovery request, so the fake has no discovery document either.
 * Mirrors OidcControllerTests, SecurityConfigOidcTests, ManagementContextResolverTests and the
 * OIDC cases of ManagementUserServiceTests on the Java server.
 */

